import csv, sys, statistics as st
from collections import Counter, defaultdict

def load(p):
    return list(csv.DictReader(open(p), delimiter='\t'))

def q(vals):
    vals = sorted(vals)
    if not vals:
        return 'n=0'
    n = len(vals)
    def pct(p):
        k = (n - 1) * p
        f = int(k); c = min(f + 1, n - 1)
        return vals[f] + (vals[c] - vals[f]) * (k - f)
    return f'n={n} sum={sum(vals)} q1={pct(.25):.0f} med={pct(.5):.0f} q3={pct(.75):.0f} max={vals[-1]} mean={sum(vals)/n:.1f}'

def num(r, k):
    v = r.get(k, '')
    try:
        return int(v)
    except ValueError:
        return 0

which = sys.argv[1]
rows = load(which)
suites = sys.argv[2].split(',') if len(sys.argv) > 2 else None
groups = defaultdict(list)
for r in rows:
